            'usingDefinition',
              case when pol.polqual is null then null
                   else btrim(replace(pg_catalog.pg_get_expr(pol.polqual, pol.polrelid), E'\r\n', E'\n'))
              end,
            'checkDefinition',
              case when pol.polwithcheck is null then null
                   else btrim(replace(pg_catalog.pg_get_expr(pol.polwithcheck, pol.polrelid), E'\r\n', E'\n'))
              end
          ) order by pol.polname)
          from pg_catalog.pg_policy as pol
          where pol.polrelid = tc.oid
        ), '[]'::jsonb),
        'acls', coalesce((
          select jsonb_agg(jsonb_build_object(
            'schema', tc.schema_name,
            'objectKind', 'table',
            'objectIdentity', format('%I.%I', tc.schema_name, tc.table_name),
            'grantee', case when acl.grantee = 0 then 'PUBLIC'
                            else pg_catalog.pg_get_userbyid(acl.grantee)
                       end,
            'privilege', acl.privilege_type,
            'grantable', acl.is_grantable
          ) order by
            case when acl.grantee = 0 then 'PUBLIC'
                 else pg_catalog.pg_get_userbyid(acl.grantee)
            end,
            acl.privilege_type,
            acl.is_grantable)
          from pg_catalog.aclexplode(coalesce(tc.relacl, pg_catalog.acldefault('r', tc.relowner))) as acl
        ), '[]'::jsonb)
      ) as row_json
    from table_catalog as tc
    join exact_counts as ec on ec.oid = tc.oid
  ),
  function_catalog as (
    select
      case when p.proname like 'ct_paid_%' then 'canonical' else 'legacy' end as scope_name,
      p.oid,
      n.nspname as schema_name,
      p.proname as function_name,
      pg_catalog.pg_get_function_identity_arguments(p.oid) as identity_arguments,
      p.prorettype as result_type_oid,
      p.proowner as owner_oid,
      p.prosecdef as security_definer,
      p.proconfig as function_config,
      p.proacl as function_acl
    from pg_catalog.pg_proc as p
    join pg_catalog.pg_namespace as n
      on n.oid = p.pronamespace and n.nspname = 'public'
    where p.proname like 'ct_paid_%'
       or p.proname in ('apply_comment_translator_paid_entitlement_evidence', 'apply_comment_translator_paid_usage', 'sync_comment_translator_paid_usage_from_entitlement')
  ),
  function_rows as (
    select
      fc.scope_name,
      fc.schema_name,
      fc.function_name,
      fc.identity_arguments,
      jsonb_build_object(
        'schema', fc.schema_name,
        'name', fc.function_name,
        'identityArguments', fc.identity_arguments,
        'resultType', pg_catalog.format_type(fc.result_type_oid, null::integer),
        'owner', pg_catalog.pg_get_userbyid(fc.owner_oid),
        'securityDefiner', fc.security_definer,
        'config', coalesce((
          select jsonb_agg(config_value order by config_value)
          from pg_catalog.unnest(coalesce(fc.function_config, array[]::text[])) as config_value
        ), '[]'::jsonb),
        'acls', coalesce((
          select jsonb_agg(jsonb_build_object(
            'schema', fc.schema_name,
            'objectKind', 'function',
            'objectIdentity', format('%I.%I(%s)', fc.schema_name, fc.function_name, fc.identity_arguments),
            'grantee', case when acl.grantee = 0 then 'PUBLIC'
                            else pg_catalog.pg_get_userbyid(acl.grantee)
                       end,
            'privilege', acl.privilege_type,
            'grantable', acl.is_grantable
          ) order by
            case when acl.grantee = 0 then 'PUBLIC'
                 else pg_catalog.pg_get_userbyid(acl.grantee)
            end,
            acl.privilege_type,
            acl.is_grantable)
          from pg_catalog.aclexplode(coalesce(fc.function_acl, pg_catalog.acldefault('f', fc.owner_oid))) as acl
        ), '[]'::jsonb),
        'definitionMd5', pg_catalog.md5(pg_catalog.pg_get_functiondef(fc.oid))
      ) as row_json
    from function_catalog as fc
  ),
  trigger_rows as (
    select
      tc.scope_name,
      jsonb_build_object(
        'tableSchema', tc.schema_name,
        'tableName', tc.table_name,
        'name', tg.tgname,
        'enabled', tg.tgenabled <> 'D',
        'functionIdentity', format('%I.%I(%s)', fn_ns.nspname, fn.proname, pg_catalog.pg_get_function_identity_arguments(fn.oid)),
        'definition', btrim(replace(pg_catalog.pg_get_triggerdef(tg.oid, true), E'\r\n', E'\n'))
      ) as row_json
    from table_catalog as tc
    join pg_catalog.pg_trigger as tg on tg.tgrelid = tc.oid and not tg.tgisinternal
    join pg_catalog.pg_proc as fn on fn.oid = tg.tgfoid
    join pg_catalog.pg_namespace as fn_ns on fn_ns.oid = fn.pronamespace
  ),
  dependency_counts as (
    select
      scope_name,
      (select count(*) from pg_catalog.pg_constraint as fk
       where fk.contype = 'f'
         and fk.confrelid in (select oid from table_catalog where scope_name = scopes.scope_name)
         and fk.conrelid not in (select oid from table_catalog where scope_name = scopes.scope_name))::bigint as inbound_foreign_keys,
      (select count(*) from pg_catalog.pg_depend as dep
       join pg_catalog.pg_rewrite as rw on dep.classid = 'pg_rewrite'::regclass and dep.objid = rw.oid
       join pg_catalog.pg_class as rel on rel.oid = rw.ev_class
       where dep.refclassid = 'pg_class'::regclass
         and dep.refobjid in (select oid from table_catalog where scope_name = scopes.scope_name)
         and rel.relkind = 'v'
         and rel.oid not in (select oid from table_catalog where scope_name = scopes.scope_name))::bigint as views,
      (select count(*) from pg_catalog.pg_depend as dep
       join pg_catalog.pg_rewrite as rw on dep.classid = 'pg_rewrite'::regclass and dep.objid = rw.oid
       join pg_catalog.pg_class as rel on rel.oid = rw.ev_class
       where dep.refclassid = 'pg_class'::regclass
         and dep.refobjid in (select oid from table_catalog where scope_name = scopes.scope_name)
         and rel.relkind = 'm'
         and rel.oid not in (select oid from table_catalog where scope_name = scopes.scope_name))::bigint as materialized_views,
      (select count(*) from pg_catalog.pg_rewrite as rw
       where rw.ev_class in (select oid from table_catalog where scope_name = scopes.scope_name)
         and rw.rulename <> '_RETURN')::bigint as rules,
      (select count(*) from pg_catalog.pg_policy as pol
       where pol.polrelid in (select oid from table_catalog where scope_name = scopes.scope_name))::bigint as policies,
      (select count(*) from pg_catalog.pg_trigger as tg
       where tg.tgrelid in (select oid from table_catalog where scope_name = scopes.scope_name)
         and not tg.tgisinternal)::bigint as user_triggers,
      (select count(*) from pg_catalog.pg_depend as dep
       where dep.refclassid = 'pg_event_trigger'::regclass
         and dep.refobjid in (select oid from table_catalog where scope_name = scopes.scope_name))::bigint as event_triggers,
      (select count(*) from pg_catalog.pg_publication_rel as pub
       where pub.prrelid in (select oid from table_catalog where scope_name = scopes.scope_name))::bigint as publications,
      (select count(*) from pg_catalog.pg_proc as outside_fn
       join pg_catalog.pg_namespace as outside_ns on outside_ns.oid = outside_fn.pronamespace
       where outside_ns.nspname = 'public'
         and outside_fn.oid not in (
           select oid from function_catalog where scope_name = scopes.scope_name
         )
         and exists (
           select 1 from table_catalog as scoped_table
           where scoped_table.scope_name = scopes.scope_name
             and position(format('%I.%I', scoped_table.schema_name, scoped_table.table_name)
               in pg_catalog.pg_get_functiondef(outside_fn.oid)) > 0
         ))::bigint as outside_function_source_references,
      (select count(*) from pg_catalog.pg_depend as dep
       where dep.deptype = 'n'
         and (
           (dep.classid = 'pg_class'::regclass and dep.objid in (select oid from table_catalog where scope_name = scopes.scope_name))
           or (dep.classid = 'pg_proc'::regclass and dep.objid in (select oid from function_catalog where scope_name = scopes.scope_name))
           or (dep.refclassid = 'pg_class'::regclass and dep.refobjid in (select oid from table_catalog where scope_name = scopes.scope_name))
           or (dep.refclassid = 'pg_proc'::regclass and dep.refobjid in (select oid from function_catalog where scope_name = scopes.scope_name))
         ))::bigint as unexpected_pg_depend_edges
    from (values ('canonical'::text), ('legacy'::text)) as scopes(scope_name)
  ),
  states as (
    select
      scopes.scope_name,
      jsonb_build_object(
        'tables', coalesce((select jsonb_agg((case when scopes.scope_name = 'canonical' then row_json - 'rowCount' else row_json end) order by schema_name, table_name) from table_rows where scope_name = scopes.scope_name), '[]'::jsonb),
        'functions', coalesce((select jsonb_agg(row_json order by schema_name, function_name, identity_arguments) from function_rows where scope_name = scopes.scope_name), '[]'::jsonb),
        'triggers', coalesce((select jsonb_agg(row_json order by row_json->>'tableSchema', row_json->>'tableName', row_json->>'name') from trigger_rows where scope_name = scopes.scope_name), '[]'::jsonb),
        'dependencyCounts', (
          select jsonb_build_object(
            'inboundForeignKeys', inbound_foreign_keys,
            'views', views,
            'materializedViews', materialized_views,
            'rules', rules,
            'policies', policies,
            'userTriggers', user_triggers,
            'eventTriggers', event_triggers,
            'publications', publications,
            'outsideFunctionSourceReferences', outside_function_source_references,
            'unexpectedPgDependEdges', unexpected_pg_depend_edges
          )
          from dependency_counts
          where dependency_counts.scope_name = scopes.scope_name
        )
      ) as state
    from (values ('canonical'::text), ('legacy'::text)) as scopes(scope_name)
  )
  select jsonb_object_agg(scope_name, state)
  into v_states
  from states;

  v_actual_legacy := v_states->'legacy';
  v_actual_canonical := v_states->'canonical';
  v_archive_schema_count := (
    select count(*) from pg_catalog.pg_namespace
    where nspname = 'comment_translator_paid_legacy_archive'
  );
  v_canonical_reserved_object_count := (
    select count(*) from (
      select c.oid
      from pg_catalog.pg_class as c
      join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname like 'comment_translator_paid_%'
        and c.relkind not in ('i', 'I')
      union all
      select p.oid
      from pg_catalog.pg_proc as p
      join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname like 'ct_paid_%'
    ) as canonical_objects
  );
  v_legacy_reserved_object_count := (
    select count(*) from (
      select c.oid
      from pg_catalog.pg_class as c
      join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname in ('comment_translator_paid_entitlements', 'comment_translator_paid_usage_counters', 'comment_translator_paid_usage_events')
        and c.relkind not in ('i', 'I')
      union all
      select p.oid
      from pg_catalog.pg_proc as p
      join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname in ('apply_comment_translator_paid_entitlement_evidence', 'apply_comment_translator_paid_usage', 'sync_comment_translator_paid_usage_from_entitlement')
    ) as legacy_objects
  );
  v_a2_reserved_object_count := v_canonical_reserved_object_count + v_legacy_reserved_object_count;

  if v_actual_legacy is not distinct from v_expected_legacy
     and v_actual_canonical is not distinct from v_expected_clean
     and v_archive_schema_count = 0 then
    v_state := 'exact-legacy';
  elsif v_actual_canonical is not distinct from v_expected_canonical
        and v_actual_legacy is not distinct from v_expected_clean
        and v_archive_schema_count = 0 then
    v_state := 'exact-canonical';
  elsif v_actual_canonical is not distinct from v_expected_preview_entry
        and v_canonical_reserved_object_count = jsonb_array_length(v_expected_preview_entry->'tables')
          + jsonb_array_length(v_expected_preview_entry->'functions')
        and v_actual_legacy is not distinct from v_expected_clean
        and v_archive_schema_count = 0 then
    v_state := 'exact-preview-entry';
  elsif v_a2_reserved_object_count = 0 and v_archive_schema_count = 0 then
    v_state := 'exact-clean';
  else
    raise exception 'Gate 1 bridge state is partial, mixed, or unknown';
  end if;

  if to_regclass('cron.job') is null then
    raise exception 'Gate 1 Paid Cron catalog is unavailable';
  end if;
  if v_state = 'exact-preview-entry' then
    if exists (
      select 1 from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relname in (
        'comment_translator_creator_history', 'comment_translator_custom_dictionary_entries',
        'comment_translator_moderator_share_browser_sessions', 'comment_translator_moderator_share_tokens',
        'comment_translator_obs_overlay_browser_sessions', 'comment_translator_obs_overlay_tokens'
      )
    ) or exists (
      select 1 from pg_catalog.pg_proc p
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname in (
        'create_comment_translator_custom_dictionary_entry', 'delete_comment_translator_custom_dictionary_entry',
        'revoke_comment_translator_moderator_share_token', 'revoke_comment_translator_obs_overlay_token',
        'update_comment_translator_custom_dictionary_entry', 'write_comment_translator_moderator_share_token',
        'write_comment_translator_obs_overlay_token'
      )
    ) then
      raise exception 'Gate 1 observed Preview source-era objects exist';
    end if;
    if (select count(*) from cron.job where jobname = 'comment-translator-paid-maintenance') <> 1
       or not exists (
         select 1 from cron.job
         where jobname = 'comment-translator-paid-maintenance'
           and active is false
           and schedule = '*/5 * * * *'
           and command = 'select private.ct_paid_invoke_maintenance_from_vault();'
           and database = 'postgres' and username = 'postgres'
           and nodename = 'localhost' and nodeport = 5432
       ) then
      raise exception 'Gate 1 observed Preview Cron metadata mismatch';
    end if;
    if to_regclass('vault.secrets') is null then
      raise exception 'Gate 1 observed Preview Vault metadata unavailable';
    end if;
    if (select coalesce(jsonb_agg(name order by name), '[]'::jsonb)
        from vault.secrets
        where name like 'comment_translator_paid_%')
       is distinct from '["comment_translator_paid_cron_token","comment_translator_paid_maintenance_url"]'::jsonb then
      raise exception 'Gate 1 observed Preview Vault metadata mismatch';
    end if;
  elsif exists (select 1 from cron.job where jobname = 'comment-translator-paid-maintenance') then
    raise exception 'Gate 1 Paid Cron job already exists';
  end if;

  if v_state = 'exact-preview-entry' then
    if v_actual_canonical is distinct from v_expected_preview_entry
       or v_actual_legacy is distinct from v_expected_clean then
      raise exception 'Gate 1 observed Preview state changed during selection';
    end if;
  elsif v_state = 'exact-canonical' then
    if v_actual_canonical is distinct from v_expected_canonical
       or v_actual_legacy is distinct from v_expected_clean then
      raise exception 'Gate 1 canonical state changed during selection';
    end if;
  elsif v_state = 'exact-clean' then
    if v_a2_reserved_object_count <> 0
       or v_actual_legacy is distinct from v_expected_clean
       or v_actual_canonical is distinct from v_expected_clean then
      raise exception 'Gate 1 clean state changed during selection';
    end if;
  elsif v_state = 'exact-legacy' then
    if v_archive_schema_count <> 0 then
      raise exception 'Gate 1 legacy archive already exists';
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_actual_legacy->'tables') as row
      where row->>'owner' <> current_user
    ) or exists (
      select 1 from jsonb_array_elements(v_actual_legacy->'functions') as row
      where row->>'owner' <> current_user
    ) then
      raise exception 'Gate 1 legacy object owner is not the migration executor';
    end if;
    if (v_actual_legacy->'dependencyCounts'->>'inboundForeignKeys')::bigint <> 0
       or (v_actual_legacy->'dependencyCounts'->>'views')::bigint <> 0
       or (v_actual_legacy->'dependencyCounts'->>'materializedViews')::bigint <> 0
       or (v_actual_legacy->'dependencyCounts'->>'rules')::bigint <> 0
       or (v_actual_legacy->'dependencyCounts'->>'eventTriggers')::bigint <> 0
       or (v_actual_legacy->'dependencyCounts'->>'publications')::bigint <> 0
       or (v_actual_legacy->'dependencyCounts'->>'outsideFunctionSourceReferences')::bigint <> 0 then
      raise exception 'Gate 1 external dependency precondition failed';
    end if;

    create schema comment_translator_paid_legacy_archive;

    alter table public.comment_translator_paid_entitlements
      set schema comment_translator_paid_legacy_archive;
    alter table public.comment_translator_paid_usage_counters
      set schema comment_translator_paid_legacy_archive;
    alter table public.comment_translator_paid_usage_events
      set schema comment_translator_paid_legacy_archive;

    alter function public.apply_comment_translator_paid_entitlement_evidence(
      text, text, text, text, text, timestamp with time zone, text, timestamp with time zone, timestamp with time zone
    ) set schema comment_translator_paid_legacy_archive;
    alter function public.apply_comment_translator_paid_usage(
      text, timestamp with time zone, text, timestamp with time zone, bigint, bigint, bigint
    ) set schema comment_translator_paid_legacy_archive;
    alter function public.sync_comment_translator_paid_usage_from_entitlement()
      set schema comment_translator_paid_legacy_archive;

    alter table comment_translator_paid_legacy_archive.comment_translator_paid_entitlements
      disable trigger comment_translator_paid_usage_sync_from_entitlement;

    revoke all on schema comment_translator_paid_legacy_archive
      from public, anon, authenticated, service_role;
    revoke all on table comment_translator_paid_legacy_archive.comment_translator_paid_entitlements
      from public, anon, authenticated, service_role;
    revoke all on table comment_translator_paid_legacy_archive.comment_translator_paid_usage_counters
      from public, anon, authenticated, service_role;
    revoke all on table comment_translator_paid_legacy_archive.comment_translator_paid_usage_events
      from public, anon, authenticated, service_role;
    revoke all on function comment_translator_paid_legacy_archive.apply_comment_translator_paid_entitlement_evidence(
      text, text, text, text, text, timestamp with time zone, text, timestamp with time zone, timestamp with time zone
    ) from public, anon, authenticated, service_role;
    revoke all on function comment_translator_paid_legacy_archive.apply_comment_translator_paid_usage(
      text, timestamp with time zone, text, timestamp with time zone, bigint, bigint, bigint
    ) from public, anon, authenticated, service_role;
    revoke all on function comment_translator_paid_legacy_archive.sync_comment_translator_paid_usage_from_entitlement()
      from public, anon, authenticated, service_role;

    if (select count(*)
        from pg_catalog.pg_class as c
        join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
        where n.nspname = 'comment_translator_paid_legacy_archive'
          and c.relkind in ('r', 'p')
          and c.relname in ('comment_translator_paid_entitlements', 'comment_translator_paid_usage_counters', 'comment_translator_paid_usage_events')) <> 3 then
      raise exception 'Gate 1 archive table count mismatch';
    end if;
    if (select count(*)
        from pg_catalog.pg_proc as p
        join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
        where n.nspname = 'comment_translator_paid_legacy_archive'
          and p.proname in ('apply_comment_translator_paid_entitlement_evidence', 'apply_comment_translator_paid_usage', 'sync_comment_translator_paid_usage_from_entitlement')) <> 3 then
      raise exception 'Gate 1 archive function count mismatch';
    end if;
    if exists (
      select 1 from pg_catalog.pg_class as c
      join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relname in ('comment_translator_paid_entitlements', 'comment_translator_paid_usage_counters', 'comment_translator_paid_usage_events')
    ) or exists (
      select 1 from pg_catalog.pg_proc as p
      join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname in ('apply_comment_translator_paid_entitlement_evidence', 'apply_comment_translator_paid_usage', 'sync_comment_translator_paid_usage_from_entitlement')
    ) then
      raise exception 'Gate 1 public legacy names remain';
    end if;
    if to_regprocedure('public.apply_comment_translator_paid_entitlement_evidence(text,text,text,text,text,timestamp with time zone,text,timestamp with time zone,timestamp with time zone)') is not null
       or to_regprocedure('public.apply_comment_translator_paid_usage(text,timestamp with time zone,text,timestamp with time zone,bigint,bigint,bigint)') is not null
       or to_regprocedure('public.sync_comment_translator_paid_usage_from_entitlement()') is not null then
      raise exception 'Gate 1 public legacy identity remains';
    end if;
    select count(*) into v_row_count from comment_translator_paid_legacy_archive.comment_translator_paid_entitlements;
    if v_row_count <> 0 then raise exception 'Gate 1 archived entitlement rows are nonzero'; end if;
    select count(*) into v_row_count from comment_translator_paid_legacy_archive.comment_translator_paid_usage_counters;
    if v_row_count <> 0 then raise exception 'Gate 1 archived counter rows are nonzero'; end if;
    select count(*) into v_row_count from comment_translator_paid_legacy_archive.comment_translator_paid_usage_events;
    if v_row_count <> 0 then raise exception 'Gate 1 archived event rows are nonzero'; end if;
    if exists (
      select 1 from pg_catalog.pg_class as c
      join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
      where n.nspname = 'comment_translator_paid_legacy_archive'
        and c.relname in ('comment_translator_paid_entitlements', 'comment_translator_paid_usage_counters', 'comment_translator_paid_usage_events')
        and not c.relrowsecurity
    ) then
      raise exception 'Gate 1 archived RLS drift';
    end if;
    if not exists (
      select 1
      from pg_catalog.pg_trigger as tg
      join pg_catalog.pg_class as c on c.oid = tg.tgrelid
      join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
      where n.nspname = 'comment_translator_paid_legacy_archive'
        and c.relname = 'comment_translator_paid_entitlements'
        and tg.tgname = 'comment_translator_paid_usage_sync_from_entitlement'
        and not tg.tgisinternal
        and tg.tgenabled = 'D'
    ) then
      raise exception 'Gate 1 archived trigger is not disabled';
    end if;
    if exists (
      select 1
      from (
        select coalesce(n.nspacl, pg_catalog.acldefault('n', n.nspowner)) as acl
        from pg_catalog.pg_namespace as n
        where n.nspname = 'comment_translator_paid_legacy_archive'
        union all
        select coalesce(c.relacl, pg_catalog.acldefault('r', c.relowner))
        from pg_catalog.pg_class as c
        join pg_catalog.pg_namespace as n on n.oid = c.relnamespace
        where n.nspname = 'comment_translator_paid_legacy_archive'
          and c.relkind in ('r', 'p')
        union all
        select coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))
        from pg_catalog.pg_proc as p
        join pg_catalog.pg_namespace as n on n.oid = p.pronamespace
        where n.nspname = 'comment_translator_paid_legacy_archive'
          and p.proname in ('apply_comment_translator_paid_entitlement_evidence', 'apply_comment_translator_paid_usage', 'sync_comment_translator_paid_usage_from_entitlement')
      ) as objects
      cross join lateral pg_catalog.aclexplode(objects.acl) as acl
      where acl.grantee = 0
         or pg_catalog.pg_get_userbyid(acl.grantee) in ('anon', 'authenticated', 'service_role')
    ) then
      raise exception 'Gate 1 archived application ACL is not denied';
    end if;
  end if;
end
$bridge$;
